package feature.auth.presentation.loginimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.*import androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.text.KeyboardOptionsimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.rounded.FmdGoodimport androidx.compose.material3.*import androidx.compose.runtime.*import androidx.compose.ui.Modifierimport androidx.compose.ui.res.painterResourceimport androidx.compose.ui.text.input.KeyboardTypeimport androidx.compose.ui.unit.dpimport core.ui.theme.AppTextStyleimport core.ui.components.AppButtonimport core.ui.components.AppTextFieldimport com.example.clot_shopejetbackcompose.R@Composablefun LoginScreen() {    Column(        modifier = Modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background)            .padding(horizontal = 23.dp),        verticalArrangement = Arrangement.Top,    ) {        Spacer(modifier = Modifier.height(123.dp))        // ── "Sign in" heading — H1/Bold ──────────────────────────────────────        Text(            text = "Sign in",            style = AppTextStyle.H1Bold.copy(                color = MaterialTheme.colorScheme.onBackground,            ),        )        Spacer(modifier = Modifier.height(16.dp))        AppTextField(            keyboardOptions = KeyboardOptions                (keyboardType = KeyboardType.Email),            onValueChange = {},            value = "", placeholder = "email"            , ispassword = false        )        Spacer(modifier = Modifier.height(16.dp))        AppTextField(            keyboardOptions = KeyboardOptions                (keyboardType = KeyboardType.Password),            onValueChange = {},            value = "", placeholder = "password",            ispassword = true        )        Spacer(modifier = Modifier.height(16.dp))        AppButton(            color = MaterialTheme.colorScheme.primary,            onClick = {},            text = "Sign in",        )        Spacer(Modifier.height(22.dp))        AppButton(            color = MaterialTheme.colorScheme.surface,            onClick = {},            text = "continue with google"            , icon = painterResource(R.drawable.google)        )    }}